-- EZPK v216 VOTE system
CREATE TABLE IF NOT EXISTS votes (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',vote_type TEXT NOT NULL DEFAULT 'single' CHECK(vote_type IN ('single','multiple')),status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','active','ended')),starts_at TEXT,ends_at TEXT,show_results INTEGER NOT NULL DEFAULT 0,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at TEXT,FOREIGN KEY(created_by) REFERENCES members(id));
CREATE TABLE IF NOT EXISTS vote_options (id INTEGER PRIMARY KEY AUTOINCREMENT,vote_id INTEGER NOT NULL,label TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_responses (id INTEGER PRIMARY KEY AUTOINCREMENT,vote_id INTEGER NOT NULL,member_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(vote_id,member_id),FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_response_options (response_id INTEGER NOT NULL,option_id INTEGER NOT NULL,PRIMARY KEY(response_id,option_id),FOREIGN KEY(response_id) REFERENCES vote_responses(id) ON DELETE CASCADE,FOREIGN KEY(option_id) REFERENCES vote_options(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_member_states (member_id INTEGER PRIMARY KEY,consecutive_missed_votes INTEGER NOT NULL DEFAULT 0,last_vote_id INTEGER,last_vote_status TEXT NOT NULL DEFAULT 'none',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_member_exclusions (member_id INTEGER PRIMARY KEY,excluded INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vote_eligible_members (vote_id INTEGER NOT NULL,member_id INTEGER NOT NULL,PRIMARY KEY(vote_id,member_id),FOREIGN KEY(vote_id) REFERENCES votes(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_votes_status ON votes(status,starts_at,ends_at);CREATE INDEX IF NOT EXISTS idx_vote_responses_vote ON vote_responses(vote_id);CREATE INDEX IF NOT EXISTS idx_vote_state_streak ON vote_member_states(consecutive_missed_votes DESC);